# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.parsing import parse_span
from hourglass.models import Shift
from hourglass.errors import ProjectError

def shift(worker, day, text):
    return Shift(worker, day, parse_span(text))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            shift("Ana", "mon", "09:00-10:00"),
            shift("Brisa", "mon", "09:00-13:30"),
            shift("Brisa", "tue", "09:00-12:00"),
            shift("Cy", "wed", "09:00-11:00")
        ])
        self.assertEqual(lines, [
            "Brisa: 2 shifts, 7.5 hours",
            "Cy: 1 shift, 2.0 hours",
            "Ana: 1 shift, 1.0 hours"
        ])

    def test_one_decimal_place(self):
        lines = timesheet_lines(
            [shift("Ana", "mon", "09:00-09:20")]
        )
        self.assertEqual(
            lines, ["Ana: 1 shift, 0.3 hours"]
        )

    def test_ties_break_on_name(self):
        lines = timesheet_lines([
            shift("Zed", "mon", "09:00-10:00"),
            shift("Amy", "tue", "09:00-10:00")
        ])
        self.assertTrue(lines[0].startswith("Amy"))

    def test_accepts_any_iterable(self):
        rows = iter([shift("Ana", "mon", "09:00-10:00")])
        self.assertEqual(len(timesheet_lines(rows)), 1)

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        for name in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines(
                    [shift(name, "mon", "09:00-10:00")]
                )
